package com.android.tools.lint.checks;

import com.android.tools.lint.detector.api.*;
import org.jetbrains.annotations.NotNull;
import java.io.File;
import java.util.*;

public class IconDetector extends Detector implements ResourceFolderScanner {
    public static final Issue ISSUE = Issue.create(
        "IconMixedNinePatch",
        "Clashing PNG and 9-PNG files",
        "If you accidentally name two separate resources `file.png` and `file.9.png`, " +
        "the image file and the nine patch file will both map to the same drawable " +
        "resource, `@drawable/file`, which is probably not what was intended.",
        Category.ICONS,
        6,
        Severity.WARNING,
        new Implementation(IconDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override
    public void checkFolder(@NotNull ResourceFolderContext context) {
        // Only check drawable/mipmap folders
        ResourceFolderType folderType = context.getFolderType();
        if (folderType != ResourceFolderType.DRAWABLE && folderType != ResourceFolderType.MIPMAP) {
            return;
        }

        File folder = context.getFolder();
        File[] files = folder.listFiles();
        if (files == null) return;

        Map<String, File> pngFiles = new HashMap<>();
        Map<String, File> ninePatchFiles = new HashMap<>();

        for (File file : files) {
            String name = file.getName();
            if (name.endsWith(".9.png")) {
                String base = name.substring(0, name.length() - 6); // remove .9.png
                ninePatchFiles.put(base, file);
            } else if (name.endsWith(".png")) {
                String base = name.substring(0, name.length() - 4); // remove .png
                pngFiles.put(base, file);
            }
        }

        for (Map.Entry<String, File> entry : pngFiles.entrySet()) {
            String base = entry.getKey();
            if (ninePatchFiles.containsKey(base)) {
                File png = entry.getValue();
                File ninePatch = ninePatchFiles.get(base);
                // Report on the png file, or both? Usually report on one and mention the other.
                context.report(ISSUE, Location.create(png),
                    "Both `png` and `9.png` files found with the same base name: " + base);
            }
        }
    }
}
```

